&lt;b&gt;Port&#233;e&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Portee.html&quot; title=&quot;personnelle&quot;&gt;personnelle&lt;/a&gt;&lt;br/&gt;
&lt;b&gt;Cible&lt;/b&gt; le jeteur de sorts&lt;br/&gt;
&lt;b&gt;Dur&#233;e&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts.html#DUREE&quot; title=&quot;Pr&#233;sentation des sorts&quot;&gt;concentration&lt;/a&gt;&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;float:right; padding-left: 6px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs-(Magie-Et-Sorts).html#5&quot; title=&quot;FAQ du Manuel des joueurs, section magie et sorts&quot;&gt;→&lt;/a&gt; &lt;i&gt;Contact avec les plans&lt;/i&gt; : Puis-je faire 10 au test d’Intelligence impos&#233; par ce sort ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Voir son Int et son Cha r&#233;duits &#224; 8 par une entit&#233; extraplanaire repr&#233;sente une menace significative, par cons&#233;quent le personnage ne peut pas faire 10 &#224; ce test. &lt;i&gt;(Retour au &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contact-Avec-Les-Plans.html&quot; title=&quot;Contact avec les plans&quot;&gt;sort&lt;/a&gt;&lt;/u&gt;)&lt;/i&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:50px; cursor:pointer&quot; src=&quot;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&quot; title=&quot;Cliquez pour afficher/cacher une FAQ officielle relative &#224; ce texte&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
